// План: specs/security.md, тесты 1.1–1.4. Кейсы: .qa/tests/security/SEC-001…003. Тикет #6a9e9592f020cfee7fb9cb5e (REVOKE).
// API-тест прав PostgREST. Ничего не создаёт и не меняет:
//  - PATCH пишет ТЕКУЩЕЕ значение колонки (даже принятая запись ничего бы не изменила);
//  - INSERT — с несуществующими FK (без привилегии → 401/403; с привилегией БД отклонила бы по FK, строка не создаётся);
//  - UPDATE/DELETE append-only таблиц — по несуществующему id.
// Проверка прав в Postgres идёт раньше проверки строк, поэтому 401/403 = колонка/таблица защищена.
import { test, expect, APIRequestContext, APIResponse } from '@playwright/test';
import * as fs from 'fs';
import * as path from 'path';

const NOPE = '00000000-0000-4000-8000-000000000000';
const CLIENT_STATE = path.resolve(__dirname, '../../../auth/client.json');
const QA = JSON.parse(fs.readFileSync(path.resolve(__dirname, '../../qa.config.json'), 'utf8'));
const BASE_URL: string = process.env.QA_BASE_URL || QA.baseUrl;

type Creds = { base: string; apikey: string; authorization: string; userId: string };
let creds: Creds;

function jwtPayload(token: string): Record<string, unknown> {
  const part = token.replace(/^Bearer\s+/i, '').split('.')[1] ?? '';
  return JSON.parse(Buffer.from(part, 'base64url').toString('utf8'));
}

// Берём apikey и JWT пользователя из первого запроса приложения к /rest/v1/ под сессией client.
test.beforeAll(async ({ browser }) => {
  const context = await browser.newContext({ storageState: CLIENT_STATE });
  const page = await context.newPage();
  const reqPromise = page.waitForRequest((r) => {
    if (!r.url().includes('/rest/v1/')) return false;
    const auth = r.headers()['authorization'];
    if (!auth) return false;
    try {
      return jwtPayload(auth).role === 'authenticated';
    } catch {
      return false;
    }
  }, { timeout: 30_000 });
  await page.goto(BASE_URL + '/wallet');
  const req = await reqPromise;
  const h = req.headers();
  const sub = jwtPayload(h['authorization']).sub;
  expect(sub, 'нет sub в JWT — сессия client истекла? (npm run qa-login)').toBeTruthy();
  creds = {
    base: req.url().split('/rest/v1/')[0] + '/rest/v1/',
    apikey: h['apikey'],
    authorization: h['authorization'],
    userId: String(sub),
  };
  await context.close();
});

function headers(anon: boolean): Record<string, string> {
  const h: Record<string, string> = { apikey: creds.apikey, 'content-type': 'application/json', prefer: 'return=minimal' };
  if (!anon) h.authorization = creds.authorization;
  return h;
}

async function call(
  request: APIRequestContext,
  method: 'GET' | 'PATCH' | 'POST' | 'DELETE',
  p: string,
  body?: unknown,
  anon = false,
): Promise<APIResponse> {
  return request.fetch(creds.base + p, {
    method,
    headers: headers(anon),
    data: body === undefined ? undefined : JSON.stringify(body),
    failOnStatusCode: false,
  });
}

async function getRows<T>(request: APIRequestContext, p: string): Promise<T[]> {
  const r = await call(request, 'GET', p);
  expect(r.status(), `GET ${p}: ${await r.text()}`).toBe(200);
  return (await r.json()) as T[];
}

async function expectDenied(r: APIResponse, status: 401 | 403, label: string) {
  const text = await r.text();
  expect.soft(r.status(), `${label} → ${r.status()} ${text.slice(0, 160)}`).toBe(status);
  expect.soft(text, `${label}: ожидался код 42501 permission denied`).toContain('42501');
}

test.describe('אבטחה — הרשאות כתיבה ב-PostgREST (REVOKE)', () => {
  test('client: עמודות מוגנות ב-wallets/deals/users — PATCH בערך הנוכחי → 403 @desktop @prod-safe #6a9e9592', async ({ request }) => {
    type Wallet = { id: string; available_balance: number; escrow_balance: number; awaiting_release_balance: number };
    type Deal = { id: string; money_state: string; cancellation_requested_by: string | null; payer_id: string; payee_id: string };
    type User = { id: string; kyc_status: string | null; phone: string | null };

    const wSelect = 'select=id,available_balance,escrow_balance,awaiting_release_balance';
    const [w] = await getRows<Wallet>(request, `wallets?${wSelect}&limit=1`);
    expect(w, 'у client нет кошелька').toBeTruthy();
    const me = creds.userId;
    const [d] = await getRows<Deal>(
      request,
      `deals?select=id,money_state,cancellation_requested_by,payer_id,payee_id&or=(payer_id.eq.${me},payee_id.eq.${me})&limit=1`,
    );
    expect(d, 'у client нет ни одной сделки').toBeTruthy();
    const [u] = await getRows<User>(request, `users?select=id,kyc_status,phone&id=eq.${me}`);
    expect(u, 'не найдена строка users для client').toBeTruthy();

    // AC1 — три баланса кошелька.
    for (const col of ['available_balance', 'escrow_balance', 'awaiting_release_balance'] as const) {
      await expectDenied(await call(request, 'PATCH', `wallets?id=eq.${w.id}`, { [col]: w[col] }), 403, `PATCH wallets.${col}`);
    }
    // AC2/AC3 — состояние денег, запрос отмены, стороны сделки.
    for (const col of ['money_state', 'cancellation_requested_by', 'payer_id', 'payee_id'] as const) {
      await expectDenied(await call(request, 'PATCH', `deals?id=eq.${d.id}`, { [col]: d[col] }), 403, `PATCH deals.${col}`);
    }
    // AC4 — KYC и телефон.
    for (const col of ['kyc_status', 'phone'] as const) {
      await expectDenied(await call(request, 'PATCH', `users?id=eq.${u.id}`, { [col]: u[col] }), 403, `PATCH users.${col}`);
    }

    // Баланс не изменился.
    const [after] = await getRows<Wallet>(request, `wallets?${wSelect}&id=eq.${w.id}`);
    expect(after).toEqual(w);
  });

  test('client: INSERT deals עם money_state / cancellation_requested_by → 403 @desktop @prod-safe #6a9e9592', async ({ request }) => {
    const common = { payer_id: NOPE, payee_id: NOPE, title: 'QA-AUTO-REVOKE-PROBE', amount: 1 };
    await expectDenied(await call(request, 'POST', 'deals', { ...common, money_state: 'released' }), 403, 'INSERT deals.money_state');
    await expectDenied(
      await call(request, 'POST', 'deals', { ...common, cancellation_requested_by: NOPE }),
      403,
      'INSERT deals.cancellation_requested_by',
    );
  });

  test('client: deal_events / money_movements append-only — INSERT/UPDATE/DELETE → 403 @desktop @prod-safe #6a9e9592', async ({ request }) => {
    await expectDenied(await call(request, 'POST', 'deal_events', { deal_id: NOPE }), 403, 'INSERT deal_events');
    await expectDenied(await call(request, 'PATCH', `deal_events?id=eq.${NOPE}`, { deal_id: NOPE }), 403, 'UPDATE deal_events');
    await expectDenied(await call(request, 'DELETE', `deal_events?id=eq.${NOPE}`), 403, 'DELETE deal_events');
    await expectDenied(await call(request, 'POST', 'money_movements', { wallet_id: NOPE }), 403, 'INSERT money_movements');
    await expectDenied(await call(request, 'PATCH', `money_movements?id=eq.${NOPE}`, { wallet_id: NOPE }), 403, 'UPDATE money_movements');
    await expectDenied(await call(request, 'DELETE', `money_movements?id=eq.${NOPE}`), 403, 'DELETE money_movements');
  });

  test('anon: PATCH/INSERT ב-public → 401 @desktop @prod-safe #6a9e9592', async ({ request }) => {
    await expectDenied(await call(request, 'PATCH', `wallets?id=eq.${NOPE}`, { available_balance: 0 }, true), 401, 'anon PATCH wallets');
    await expectDenied(await call(request, 'PATCH', `deals?id=eq.${NOPE}`, { title: 'x' }, true), 401, 'anon PATCH deals');
    await expectDenied(await call(request, 'PATCH', `users?id=eq.${NOPE}`, { full_name: 'x' }, true), 401, 'anon PATCH users');
    await expectDenied(await call(request, 'POST', 'deal_events', { deal_id: NOPE }, true), 401, 'anon INSERT deal_events');
    await expectDenied(await call(request, 'POST', 'chat_messages', { deal_id: NOPE, body: 'x' }, true), 401, 'anon INSERT chat_messages');
  });
});
